-- Stage-Gate lifecycle module (ported from 30-Day_Quick_Win_Challenge). Self-contained sg_* tables,
-- keyed by project name exactly like the source so data copies 1:1.
create table if not exists sg_lifecycle_phases (code text primary key, sort_order integer not null, phase_group text not null check (phase_group in ('fel','execution','commissioning')), title text not null, responsible text not null, gate_name text not null, gate_threshold_pct numeric not null check (gate_threshold_pct between 0 and 100), progress_engine text not null check (progress_engine in ('step','basic_design','epc')), icon_key text not null default 'target', objectives_weight_pct numeric not null default 50 check (objectives_weight_pct >= 0), outputs_weight_pct numeric not null default 30 check (outputs_weight_pct >= 0), criteria_weight_pct numeric not null default 20 check (criteria_weight_pct >= 0), is_active boolean not null default true, updated_at timestamptz not null default now(), constraint sg_phases_weights_sum check (objectives_weight_pct + outputs_weight_pct + criteria_weight_pct = 100));
create table if not exists sg_lifecycle_objectives (id bigint generated by default as identity primary key, phase_code text not null references sg_lifecycle_phases(code) on delete cascade, seq integer not null default 0, title text not null, description text, weight numeric check (weight is null or weight >= 0), is_active boolean not null default true);
create table if not exists sg_lifecycle_outputs (id bigint generated by default as identity primary key, phase_code text not null references sg_lifecycle_phases(code) on delete cascade, seq integer not null default 0, title text not null, description text, weight numeric check (weight is null or weight >= 0), is_active boolean not null default true);
create table if not exists sg_lifecycle_criteria (id bigint generated by default as identity primary key, phase_code text not null references sg_lifecycle_phases(code) on delete cascade, seq integer not null default 0, title text not null, description text, weight numeric check (weight is null or weight >= 0), is_mandatory boolean not null default true, is_active boolean not null default true);
create table if not exists sg_lifecycle_phase_durations (phase_code text primary key references sg_lifecycle_phases(code), duration_days integer not null check (duration_days > 0), updated_at timestamptz not null default now(), updated_by text);
create table if not exists sg_lifecycle_strategy_phase_dependencies (id bigint generated by default as identity primary key, strategy text not null check (strategy in ('sequential','overlapping','fast_track','emergency_fast_track')), pred_phase_code text not null references sg_lifecycle_phases(code), succ_phase_code text not null references sg_lifecycle_phases(code), dep_type text not null check (dep_type in ('FS','SS','FF','SF')), lag_days integer not null default 0, unique (strategy, succ_phase_code));
create table if not exists sg_lifecycle_master_schedule_versions (id bigint generated by default as identity primary key, project_name text not null, version_label text not null, is_baseline boolean not null default false, execution_strategy text not null, project_start_date date not null, startup_date date, completion_date date, total_duration_days integer, change_reason text, created_by text not null, created_at timestamptz not null default now(), unique (project_name, version_label));
create table if not exists sg_lifecycle_master_schedule (id bigint generated by default as identity primary key, project_name text not null unique, execution_strategy text not null default 'sequential' check (execution_strategy in ('sequential','overlapping','fast_track','emergency_fast_track')), project_start_date date, governance_status text not null default 'draft' check (governance_status in ('draft','proposed','reviewed','approved','baseline','in_execution','revised','completed')), active_baseline_version_id bigint references sg_lifecycle_master_schedule_versions(id), updated_at timestamptz not null default now(), updated_by text);
create table if not exists sg_lifecycle_schedule_items (id bigint generated by default as identity primary key, project_name text not null, phase_code text not null references sg_lifecycle_phases(code), parent_id bigint references sg_lifecycle_schedule_items(id) on delete cascade, seq integer not null default 0, title text not null, planned_start date, planned_finish date, weight_pct numeric check (weight_pct is null or weight_pct >= 0), manual_actual_pct numeric check (manual_actual_pct is null or manual_actual_pct between 0 and 100), updated_at timestamptz not null default now(), updated_by text, constraint sg_items_finish_after_start check (planned_finish is null or planned_start is null or planned_finish >= planned_start));
create table if not exists sg_lifecycle_schedule_dependencies (id bigint generated by default as identity primary key, project_name text not null, predecessor_id bigint not null references sg_lifecycle_schedule_items(id) on delete cascade, successor_id bigint not null references sg_lifecycle_schedule_items(id) on delete cascade, dep_type text not null default 'FS' check (dep_type in ('FS','SS','FF','SF')), lag_days numeric not null default 0, updated_at timestamptz not null default now(), check (predecessor_id <> successor_id), unique (predecessor_id, successor_id));
create table if not exists sg_lifecycle_schedule_baselines (id bigint generated by default as identity primary key, project_name text not null, label text not null, created_by text not null, created_at timestamptz not null default now());
create table if not exists sg_lifecycle_schedule_baseline_items (id bigint generated by default as identity primary key, baseline_id bigint not null references sg_lifecycle_schedule_baselines(id) on delete cascade, schedule_item_id bigint not null, title text not null, planned_start date, planned_finish date, weight_pct numeric);
create table if not exists sg_lifecycle_schedule_success_templates (id bigint generated by default as identity primary key, name text not null, source_project_name text not null, execution_strategy text, total_duration_days integer, notes text, created_by text not null, created_at timestamptz not null default now());
create table if not exists sg_lifecycle_schedule_success_template_items (id bigint generated by default as identity primary key, template_id bigint not null references sg_lifecycle_schedule_success_templates(id) on delete cascade, phase_code text not null, source_item_id bigint not null, source_parent_id bigint, title text not null, day_offset_from_phase_start integer not null, duration_days integer not null, weight_pct numeric, seq integer not null);
create table if not exists sg_lifecycle_schedule_success_template_phases (id bigint generated by default as identity primary key, template_id bigint not null references sg_lifecycle_schedule_success_templates(id) on delete cascade, phase_code text not null, day_offset_start integer not null, duration_days integer not null, seq integer not null);
create table if not exists sg_project_lifecycle_phases (id bigint generated by default as identity primary key, project_name text not null, phase_code text not null references sg_lifecycle_phases(code), weight_pct numeric check (weight_pct is null or weight_pct >= 0), planned_start date, planned_finish date, actual_start date, actual_finish date, contract_value numeric, manual_actual_pct numeric check (manual_actual_pct is null or manual_actual_pct between 0 and 100), gate_status text not null default 'not_ready' check (gate_status in ('not_ready','ready_for_review','conditional','passed','blocked')), gate_requested_at timestamptz, gate_requested_by text, updated_at timestamptz not null default now(), updated_by text, unique (project_name, phase_code), constraint sg_plp_dates check ((planned_finish is null or planned_start is null or planned_finish >= planned_start) and (actual_finish is null or actual_start is null or actual_finish >= actual_start)));
create table if not exists sg_project_phase_items (id bigint generated by default as identity primary key, project_name text not null, phase_code text not null references sg_lifecycle_phases(code), kind text not null check (kind in ('objective','output','criterion')), item_id bigint not null, status text not null default 'pending' check (status in ('not_started','in_progress','completed','blocked','pending','submitted','verified','rejected','failed','waived')), owner text, due_date date, completion_date date, evidence text, comment text, submitted_by text, verified_by text, verification_date date, updated_at timestamptz not null default now(), updated_by text, evidence_file_url text, unique (project_name, phase_code, kind, item_id));
create table if not exists sg_lifecycle_gate_decisions (id bigint generated by default as identity primary key, project_name text not null, phase_code text not null references sg_lifecycle_phases(code), decision text not null check (decision in ('pass','conditional','return','cancelled')), reason text, condition_text text, condition_owner text, condition_due_date date, decided_by text not null, decided_at timestamptz not null default now());
create table if not exists sg_lifecycle_progress_history (id bigint generated by default as identity primary key, project_name text not null, phase_code text not null references sg_lifecycle_phases(code), period_label text, previous_pct numeric, new_pct numeric not null check (new_pct between 0 and 100), comment text, recorded_by text not null, recorded_at timestamptz not null default now());
create table if not exists sg_lifecycle_audit_log (id bigint generated by default as identity primary key, project_name text, phase_code text, action text not null, field text, old_value text, new_value text, changed_by text not null, changed_at timestamptz not null default now());
create table if not exists sg_projects (name text primary key, created_at timestamptz default now(), is_guide boolean not null default false, current_phase text not null default 'اجرا' check (current_phase in ('مهندسی','تأمین','اجرا','تکمیل‌شده')));
create index if not exists idx_sg_items_project on sg_lifecycle_schedule_items (project_name, phase_code);
create index if not exists idx_sg_plp_project on sg_project_lifecycle_phases (project_name);
create index if not exists idx_sg_pitems_project on sg_project_phase_items (project_name, phase_code);
